package com.bank.sort;

import java.util.*;
import java.util.logging.*;

public class CompareRefDemo {
    private static final Logger log = Logger.getLogger("Sort");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Rajesh", "Amit", "Priya"));
        SortService service = new SortService();

        service.sortNames(names);
        log.info(() -> "Sorted names: " + names);

        // equivalence check
        Comparator<String> lambda = (a, b) -> a.compareTo(b);
        Comparator<String> ref = String::compareTo;
        log.info(() -> "lambda(Amit, Priya)=" + lambda.compare("Amit", "Priya")
            + "  ref(Amit, Priya)=" + ref.compare("Amit", "Priya"));
    }
}

// ─── Would be in service/SortService.java ───
class SortService {
    void sortNames(List<String> names) {
        names.sort(String::compareTo);   // ≡ (a, b) -> a.compareTo(b)
    }
}
